xpath.script:
{
    const settings = odoo.__session_info__.user_settings || {};
    const preference = settings.rx_color_scheme || "light";
    const rendered = "";
    const wanted = preference === "system"
        ? (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light")
        : preference;
    document.cookie = `color_scheme=${wanted}; path=/; max-age=31536000; SameSite=Lax`;
    const flag = "rex_backend_theme.scheme_reload";
    if (wanted !== rendered && !sessionStorage.getItem(flag)) {
        sessionStorage.setItem(flag, "1");
        location.reload();
    } else {
        sessionStorage.removeItem(flag);
    }
}
